def load():
    cases = []
    for line in RAW.strip().split("\n"):
        title, victim, scene, roles, rooms, weapons = line.split("|")
        cases.append(dict(title=title, victim=victim, scene=scene, roles=roles.split(";"),
                          rooms=rooms.split(";"), weapons=weapons.split(";")))
    assert len(cases) == 60, len(cases)
    for c in cases:
        assert len(c["roles"]) == 6 and len(c["rooms"]) == 5 and len(c["weapons"]) == 5, c["title"]
    return cases
